import json
with open('/app/resources/treasury_bulletin_2024_12.json', 'r') as f:
    data = json.load(f)

# Find all unique keys at top level and nested levels
def find_keys(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                find_keys(v, f"{path}.{k}")
            elif k in ['title', 'name', 'header', 'table_title']:
                print(f"{path}.{k}: {v}")

find_keys(data)
